package jobs

import (
	"time"

	"github.com/vislake/speed/go/pkgcore"
	"github.com/vislake/speed/go/pkgcore/apperr"
)

// JobID identifies one enqueued Task's persisted Job record. It is
// generated by a Queue implementation when Enqueue accepts a Task, never
// supplied by the caller.
type JobID string

// Status is a Job's lifecycle state. See AGENTS.md for the full state
// diagram and transition table.
type Status string

const (
	// StatusPending is a Job's initial state: enqueued, not yet claimed by
	// a worker. A delayed or scheduled Job stays Pending — a row already
	// exists for it — until its ScheduledAt time arrives.
	StatusPending Status = "pending"

	// StatusRunning is set for the duration of exactly one Handle call.
	StatusRunning Status = "running"

	// StatusRetrying is set after a failed attempt that has not yet
	// exhausted MaxRetries. The Job becomes eligible to run again at
	// ScheduledAt, which the failed attempt's backoff computation moved
	// into the future.
	StatusRetrying Status = "retrying"

	// StatusSucceeded is terminal: Handle returned a nil error. Result
	// carries what it returned.
	StatusSucceeded Status = "succeeded"

	// StatusDeadLetter is terminal: every attempt up to MaxRetries+1 has
	// failed. Error carries the last attempt's failure message. See
	// FailureHook for the queue's one hook into this transition.
	StatusDeadLetter Status = "dead_letter"

	// StatusCancelled is terminal: Queue.Cancel was called. A Job already
	// StatusRunning when cancelled is allowed to keep executing to its own
	// completion or timeout (this package's demo implementation does not
	// preempt a running Handler goroutine — see AGENTS.md's Known
	// limitations), but whatever outcome it eventually reaches is
	// discarded in favor of StatusCancelled, which is never overwritten
	// once set.
	StatusCancelled Status = "cancelled"
)

// Terminal reports whether s is a state a Job settles into permanently: no
// worker ever transitions a Job out of a terminal status.
func (s Status) Terminal() bool {
	switch s {
	case StatusSucceeded, StatusDeadLetter, StatusCancelled:
		return true
	default:
		return false
	}
}

// Priority orders which of several eligible Jobs a worker claims next.
// Higher values run first; two Jobs of equal Priority are claimed in
// ScheduledAt order (earliest first).
type Priority int

const (
	// PriorityLow is the lowest defined Priority value.
	PriorityLow Priority = 0

	// PriorityNormal is the default Priority: Enqueue uses it whenever a
	// Task is enqueued without the WithPriority option (see queue.go).
	PriorityNormal Priority = 5

	// PriorityHigh is the highest defined Priority value.
	PriorityHigh Priority = 10
)

// Result is the opaque output of a successfully completed Job, recorded on
// Job.Result and returned to a caller polling Queue.Get. Its shape is a
// contract between whichever code enqueues a Task and the Handler
// registered for its Type — the queue itself never interprets Data.
type Result struct {
	Data []byte
}

// Job is one Task's persisted execution record: the type Queue.Enqueue,
// Queue.Get and Queue.Cancel are all built around. This shape is pinned —
// every deployment mode's Queue implementation reports the same fields.
type Job struct {
	// ID is this Job's identity, generated by Enqueue.
	ID JobID

	// Type is the Handler.Type this Job dispatches to, copied from the
	// enqueuing Task.
	Type string

	// TenantID is the tenant this Job belongs to, copied from the
	// enqueuing Task.TenantID. A worker rebuilds tenant context from
	// exactly this field before calling Handle — never from whatever
	// context the original Queue.Enqueue call happened to run in, which no
	// longer exists by the time a worker picks the Job up. See AGENTS.md's
	// "The tenant context trap" section and Handler.Handle's own doc
	// comment.
	TenantID pkgcore.TenantID

	// Payload is the enqueuing Task's opaque, caller-serialized input,
	// unchanged.
	Payload []byte

	// IdempotencyKey is the enqueuing Task's idempotency key, if any
	// (empty when the Task did not set one).
	IdempotencyKey string

	// Status is this Job's current lifecycle state.
	Status Status

	// Priority is this Job's dispatch priority.
	Priority Priority

	// ProgressPct and ProgressMsg carry the most recent values reported
	// through the ProgressFn Handle receives. Both are zero/empty until
	// the first call.
	ProgressPct int
	ProgressMsg string

	// Result is set once Status is StatusSucceeded; nil otherwise.
	Result *Result

	// Error is the most recent attempt's failure message: set when Status
	// is StatusRetrying (the failure that triggered the retry) or
	// StatusDeadLetter (the failure that exhausted retries), and cleared
	// once Status becomes StatusSucceeded. A Job cancelled after a failed
	// attempt (StatusCancelled) retains whatever message that attempt
	// recorded, for diagnostic visibility, rather than being cleared. It
	// carries err.Error() text for operator visibility, not a structured
	// *apperr.Error.
	Error string

	// Attempts is the number of times a worker has invoked Handle for this
	// Job so far, including the current or most recent one.
	Attempts int

	// MaxRetries is how many retries beyond the first attempt are allowed
	// before this Job moves to StatusDeadLetter.
	MaxRetries int

	// ScheduledAt is the earliest time a worker may claim this Job. For a
	// Job enqueued without WithDelay/WithScheduledAt it equals CreatedAt;
	// for a Job in StatusRetrying it is the backoff-computed time of the
	// next attempt.
	ScheduledAt time.Time

	// CreatedAt is when Enqueue created this Job.
	CreatedAt time.Time

	// UpdatedAt is when any field of this Job last changed.
	UpdatedAt time.Time

	// StartedAt is the most recent attempt's start time; nil before the
	// first attempt.
	StartedAt *time.Time

	// CompletedAt is set once Status becomes terminal; nil otherwise.
	CompletedAt *time.Time
}

// ErrJobNotFound is returned by Queue.Get and Queue.Cancel for an id that
// does not exist, or that exists under a tenant the caller's context
// cannot access. Both cases are deliberately indistinguishable — see
// AGENTS.md — mirroring dbkit.Repository[T].FindByID's documented collapse
// of the same two cases.
var ErrJobNotFound = apperr.NotFound("jobs.job_not_found")
